import fs from 'node:fs/promises';
import path from 'node:path';

import { build } from 'esbuild';

const entryPoints = [
  'hosts/node-cli/run.ts',
  'hosts/node-cli/run-recipe.ts',
  'hosts/node-cli/recipe-runner.ts',
  'hosts/node-cli/parse-log.ts',
];

const generatedPreamble =
  '#!/usr/bin/env node\n' +
  '// Generated from hosts/node-cli/*.ts by scripts/build-hosts.mjs. Do not edit this file directly.\n';

const checkOnly = process.argv.includes('--check');
const production = !checkOnly && process.env.NODE_ENV === 'production';

const result = await build({
  entryPoints,
  bundle: true,
  format: 'esm',
  platform: 'node',
  target: 'node20',
  outbase: 'hosts/node-cli',
  outdir: production ? 'dist/node-cli' : 'hosts/node-cli',
  sourcemap: 'inline',
  legalComments: 'none',
  treeShaking: true,
  minify: production,
  external: ['frida', 'esbuild'],
  logLevel: 'info',
  write: false,
  plugins: [
    {
      name: 'portable-source-newlines',
      setup(currentBuild) {
        currentBuild.onLoad({ filter: /\.(ts|json)$/ }, async args => ({
          contents: (await fs.readFile(args.path, 'utf8')).replace(/\r\n/g, '\n'),
          loader: args.path.endsWith('.json') ? 'json' : 'ts',
        }));
      },
    },
  ],
});

for (const outputFile of result.outputFiles ?? []) {
  if (!outputFile.path.endsWith('.js')) {
    continue;
  }

  const generatedSource = outputFile.text.replace(/^#!\/usr\/bin\/env node\r?\n/, '');
  const expected = `${generatedPreamble}${generatedSource}`;
  if (checkOnly) {
    const actual = await fs.readFile(outputFile.path, 'utf8').catch(() => '');
    if (actual.replace(/\r\n/g, '\n') !== expected) {
      throw new Error(`Generated host is stale: ${outputFile.path}; run npm run build:hosts`);
    }
  } else {
    await fs.mkdir(path.dirname(outputFile.path), { recursive: true });
    await fs.writeFile(outputFile.path, expected, 'utf8');
  }
}
